exercises.solution:
import numpy as np

X = np.array([[0,0],[0,1],[1,0],[1,1]], dtype=float)
y = np.array([0, 1, 1, 1], dtype=float)  # OR

w = np.zeros(2)
b = 0.0
lr = 0.1

def step(z):
    return 1.0 if z >= 0 else 0.0

for epoch in range(20):
    for xi, target in zip(X, y):
        pred = step(np.dot(w, xi) + b)
        error = target - pred
        w += lr * error * xi
        b += lr * error

def predict(x):
    return step(np.dot(w, np.array(x, dtype=float)) + b)
